	@Test
	void productionRegistrationRequiresRuntimeProofDescriptor() {
		Class<?> catalogType = loadCatalog();
		List<?> descriptors = invokeList(catalogType, "descriptors");
		Map<String, Object> descriptorsByRuntimeProof = new HashMap<>();
		for (Object descriptor : descriptors) {
			String runtimeProofId = invokeString(descriptor, "runtimeProofId");
			if (!runtimeProofId.isBlank()) {
				assertThat(descriptorsByRuntimeProof.put(runtimeProofId, descriptor))
						.as("runtime proof IDs are globally unique")
						.isNull();
			}
		}

		List<RuleProof> runtimeProofs = PackedRuleProofs.materialize(-1L);
		assertThat(runtimeProofs).hasSize(16);
		for (RuleProof proof : runtimeProofs) {
			Object descriptor = descriptorsByRuntimeProof.get(proof.ruleId());
			assertThat(descriptor)
					.as("production proof %s has a closed-world catalog descriptor", proof.ruleId())
					.isNotNull();
			assertThat(invokeString(descriptor, "implementationClassName"))
					.as("production proof %s names its implementation", proof.ruleId())
					.isNotBlank();
			assertThat(invokeString(descriptor, "disposition"))
					.as("production proof %s is implemented", proof.ruleId())
					.isEqualTo("IMPLEMENTED");
		}

		assertThat(invokeList(catalogType, "productionRegistrationViolations"))
				.as("catalog claims and runtime registrations agree")
				.isEmpty();
	}

