	@Test
	void memoRuleInstallationRequiresApplicableCatalogProofs() throws ReflectiveOperationException {
		Class<?> resultType = loadClass(
				"org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.RuleApplicabilityResult");
		Class<?> statusType = Class.forName(resultType.getName() + "$Status");
		assertThat(statusType.getEnumConstants())
				.extracting(Object::toString)
				.containsExactly("APPLICABLE", "NOT_APPLICABLE", "UNSAFE", "UNSUPPORTED", "BUDGET_EXHAUSTED");

		PackedQuery query = PackedQueryCodec.encode(new org.eclipse.rdf4j.query.algebra.Join(
				new org.eclipse.rdf4j.query.algebra.StatementPattern(
						org.eclipse.rdf4j.query.algebra.Var.of("s"),
						org.eclipse.rdf4j.query.algebra.Var.of("p1"),
						org.eclipse.rdf4j.query.algebra.Var.of("o1")),
				new org.eclipse.rdf4j.query.algebra.StatementPattern(
						org.eclipse.rdf4j.query.algebra.Var.of("s"),
						org.eclipse.rdf4j.query.algebra.Var.of("p2"),
						org.eclipse.rdf4j.query.algebra.Var.of("o2"))));
		PackedMemo memo = new PackedMemo(query, query.symbolCount(), 8, 8, 8, 8, 16);
		Object result = resultType.getConstructor().newInstance();
		Method proofSet = PackedMemo.class.getDeclaredMethod("internRuleProofSet", long.class);
		int wrongProofSetId = (int) proofSet.invoke(memo, PackedRuleProofs.FINITE_FILTER_VALUES);
		int validProofSetId = (int) proofSet.invoke(memo, PackedRuleProofs.FILTER_COMMUTATION);
		Method applicable = resultType.getMethod("setApplicable", int.class, int.class, int.class, long.class);
		Method install = PackedMemo.class.getDeclaredMethod("installRuleAlternative", int.class, int.class,
				int.class, int.class, int.class, int[].class, int.class, int.class, resultType);
		int source = query.rootRelId();
		int[] swappedChildren = { query.relChild(source, 1), query.relChild(source, 0) };
		int before = memo.logicalExpressionCount();

		assertMemoRejects(install, memo, source, swappedChildren, result);
		assertThat(memo.logicalExpressionCount()).isEqualTo(before);

		applicable.invoke(result, 1015, wrongProofSetId, 7, 0L);
		assertMemoRejects(install, memo, source, swappedChildren, result);
		assertThat(memo.logicalExpressionCount()).isEqualTo(before);

		applicable.invoke(result, 1015, validProofSetId, 7, 0L);
		int alternative = (int) install.invoke(memo, source, PackedRelOp.JOIN, 0, 0, 0, swappedChildren, 0, 2,
				result);
		assertThat(alternative).isGreaterThan(before);
		assertThat(memo.logicalRuleMask(alternative) & PackedRuleProofs.FILTER_COMMUTATION)
				.isEqualTo(PackedRuleProofs.FILTER_COMMUTATION);
	}

