	private static void assertMemoRejects(Method install, PackedMemo memo, int source, int[] children,
			Object result) {
		assertThatThrownByInvocation(() -> install.invoke(memo, source, PackedRelOp.JOIN, 0, 0, 0, children, 0, 2,
				result));
	}

	private static void assertThatThrownByInvocation(ThrowingInvocation invocation) {
		try {
			invocation.invoke();
			fail("memo must reject an unguarded or under-proved rule alternative");
		} catch (InvocationTargetException e) {
			assertThat(e.getCause()).isInstanceOf(PackedMemoInvariantException.class);
		} catch (ReflectiveOperationException e) {
			fail("unexpected reflection failure", e);
		}
	}

	@FunctionalInterface
	private interface ThrowingInvocation {
		void invoke() throws ReflectiveOperationException;
	}

	private static Set<String> opcodeIds(String prefix, Class<?> opcodeType) {
		Set<String> ids = new HashSet<>();
		for (Field field : opcodeType.getDeclaredFields()) {
			if (field.getType() == int.class && Modifier.isStatic(field.getModifiers())) {
				ids.add(prefix + ":" + field.getName());
			}
		}
		return ids;
	}

	private static Class<?> loadCatalog() {
		return loadClass(CATALOG_CLASS);
	}

	private static Map<String, List<Path>> testSourcesByClass(Path root) throws Exception {
		List<Path> sourceRoots = new ArrayList<>();
		for (Path moduleRoot : List.of(root.resolve("core"), root.resolve("testsuites"))) {
			try (var paths = Files.find(moduleRoot, 8,
					(path, attributes) -> attributes.isDirectory() && path.endsWith("src/test/java"))) {
				paths.forEach(sourceRoots::add);
			}
		}
		Map<String, List<Path>> sourcesByClass = new HashMap<>();
		for (Path sourceRoot : sourceRoots) {
			try (var paths = Files.walk(sourceRoot)) {
				paths.filter(Files::isRegularFile)
						.filter(path -> path.getFileName().toString().endsWith("Test.java"))
						.forEach(path -> sourcesByClass
								.computeIfAbsent(path.getFileName().toString().replaceFirst("\\.java$", ""),
										ignored -> new ArrayList<>())
								.add(path));
			}
		}
		return sourcesByClass;
	}

	private static void assertTestReferencesExist(Object descriptor, String methodName,
			Map<String, List<Path>> sourcesByClass) throws Exception {
		String stableId = invokeString(descriptor, "stableId");
		for (Object value : invokeList(descriptor, methodName)) {
			String reference = String.valueOf(value);
			int separator = reference.lastIndexOf('#');
			assertThat(separator)
					.as("%s %s reference uses Class#method: %s", stableId, methodName, reference)
					.isGreaterThan(0)
					.isLessThan(reference.length() - 1);
			String className = reference.substring(0, separator);
			className = className.substring(className.lastIndexOf('.') + 1);
			String testMethod = reference.substring(separator + 1);
			List<Path> sources = sourcesByClass.getOrDefault(className, List.of());
			assertThat(sources)
					.as("%s %s class exists: %s", stableId, methodName, className)
					.isNotEmpty();
			boolean methodExists = false;
			for (Path source : sources) {
				if (Files.readString(source).contains("void " + testMethod + "(")) {
					methodExists = true;
					break;
				}
			}
			assertThat(methodExists)
					.as("%s %s method exists: %s", stableId, methodName, reference)
					.isTrue();
		}
	}

