	private static String invokeString(Object target, String methodName) {
		Object value = invoke(target.getClass(), target, methodName);
		return value instanceof Enum<?> enumValue ? enumValue.name() : String.valueOf(value);
	}

	private static String invokeString(Class<?> type, Object target, String methodName) {
		Object value = invoke(type, target, methodName);
		return value instanceof Enum<?> enumValue ? enumValue.name() : String.valueOf(value);
	}

	private static Object invoke(Class<?> type, Object target, String methodName) {
		try {
			Method method = type.getMethod(methodName);
			return method.invoke(target);
		} catch (ReflectiveOperationException e) {
			fail("missing optimizer catalog contract: " + type.getName() + "#" + methodName, e);
			throw new AssertionError("unreachable", e);
		}
	}

	private static Path repositoryRoot() {
		Path path = Path.of(System.getProperty("user.dir")).toAbsolutePath();
		while (path != null && !Files.isDirectory(path.resolve(".agent"))) {
			path = path.getParent();
		}
		if (path == null) {
			fail("could not locate repository root from " + System.getProperty("user.dir"));
		}
		return path;
	}

	private static String sha256(Path path) throws Exception {
		try {
			return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(path)));
		} catch (NoSuchAlgorithmException e) {
			throw new AssertionError("JDK must provide SHA-256", e);
		}
	}
